# Gate 13 Factor DB Access Compliance preflight
factor_engine_path <- "factor_engine.R"
if (file.exists(factor_engine_path)) {
  fe_content <- readLines(factor_engine_path)
  violation_lines <- grep("read_parquet.*factor_db|list\\.files.*factor_db|fdb_dir", fe_content, value = FALSE)
  if (length(violation_lines) > 0) {
    stop(sprintf("[Gate 13 VIOLATION] factor_engine.R lines %s use direct factor_db access. Use load_month_factors() instead (L-164 ACTIVE).", paste(violation_lines, collapse=",")))
  }
}
